const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtN = (n) => Number(n).toLocaleString('en-IN');
const DOCCOL = { 'POL-PUR-001': '#136C76', 'POL-SUP-003': '#2E8B8B', 'POL-APR-002': '#4F7CAC', 'MAN-PUR-72': '#848B9B',
  'MAN-DD-72': '#B4B9C4', 'AMD-SUP-2026-02': '#8E6E12', 'AMD-PUR-2026-03': '#C29A2E', 'HR-CONF-007': '#A3372B' };
const ctlRow = (el, html) => { const c = document.createElement('div'); c.className = 'ctl'; c.innerHTML = html; el.appendChild(c); return c; };
const prettyJSON = (s) => { try { return JSON.stringify(JSON.parse(s), null, 1); } catch (e) { return s; } };

/* ---------- Fig 1: the naive agent's run on scenario 1, scrubbable (logs/scenarios_l2.json → naive) ---------- */
FIGS.naive = (el) => {
  const S = D.scen.naive, tr = S.trace;
  el.innerHTML = `<div class="thread" style="height:560px;font-size:18px">
    <div class="msg u"><div class="who">Kavita</div>${esc(tr[0].user)}</div>
    <div class="trace" id="nv-tr" style="flex:1;font-size:18px"></div>
    <div class="msg ag" id="nv-rep" style="max-width:100%;font-size:18px;max-height:250px;overflow:hidden"><div class="who">Agent, final reply (excerpt)</div></div></div>`;
  const ctl = ctlRow(el, `<label>Step</label><input type="range" min="1" max="${tr.length - 1}" value="1"><output></output>`);
  const inp = ctl.querySelector('input'), out = ctl.querySelector('output'), box = el.querySelector('#nv-tr'), rep = el.querySelector('#nv-rep');
  const calls = tr.filter((t) => t.call);
  const reply = S.reply;
  const lie = 'Bahi ERP enforces that POs for items with `food_contact: 1` cannot be approved or released without a valid, non-expired `FOOD-GRADE` certificate registered under the supplier\'s profile.';
  rep.innerHTML += `<div>${esc(reply.split('\n')[0].replace(/\*/g, ''))}</div><div style="margin-top:6px">… <span style="background:var(--before-soft);color:var(--before)">${esc(lie.replace(/`/g, ''))}</span> …</div>`;
  const set = (n) => {
    const seen = tr.slice(1, n + 1);
    const lines = seen.filter((t) => t.call).map((t, i) => `<div class="l"><b>${i + 1}. ${esc(t.call)}</b> ${esc(JSON.stringify(t.args))}</div>`);
    const last = seen[seen.length - 1];
    let tail = '';
    if (last && last.result) tail = `<div class="l" style="color:var(--ink-3)">→ ${esc(last.result.slice(0, 220))}…</div>`;
    box.innerHTML = `<div class="h">${lines.length} of ${calls.length} service calls · ${fmtN(S.tokens_in)} tokens in over ${S.per_call.length} model calls</div>` + lines.slice(-6).join('') + tail;
    out.textContent = `${n} / ${tr.length - 1}`;
  };
  inp.addEventListener('input', () => set(+inp.value));
  return { step(k) { const n = k >= 1 ? tr.length - 1 : Math.min(8, tr.length - 1); inp.value = n; set(n); rep.style.opacity = k >= 1 ? 1 : 0.1; } };
};

/* ---------- Fig 2: the corpus, tokens per document ---------- */
FIGS.corpus = (el) => {
  const P = window.Plates, W = 880, H = 600;
  const svg = P.svgEl('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, el);
  const docs = [...D.corpus].sort((a, b) => b.tokens - a.tokens);
  const max = docs[0].tokens, x0 = 290, bw = 290;
  const rows = docs.map((d, i) => {
    const y = 30 + i * 66;
    P.txt(svg, x0 - 14, y + 20, d.id, 'font:600 18px var(--mono);fill:var(--ink)', 'end');
    P.txt(svg, x0 - 14, y + 42, d.title.length > 24 ? d.title.slice(0, 23) + '…' : d.title, 'font:18px var(--serif);fill:var(--ink-2)', 'end');
    const r = P.svgEl('rect', { x: x0, y: y + 6, height: 36, width: 0, style: `fill:${DOCCOL[d.id]};transition:width .7s ease` }, svg);
    const t = P.txt(svg, x0 + 8, y + 30, '', 'font:600 18px var(--mono);fill:var(--ink)');
    const t2 = P.txt(svg, x0 + 8, y + 58, '', 'font:18px var(--mono);fill:var(--ink-3)');
    return { d, r, t, t2 };
  });
  const tot = D.corpus.reduce((s, d) => s + d.tokens, 0);
  const foot = P.txt(svg, x0, H - 14, '', 'font:18px var(--mono);fill:var(--ink-2)');
  return { step(k) {
    rows.forEach(({ d, r, t, t2 }) => {
      const w = Math.max(4, bw * d.tokens / max);
      r.setAttribute('width', w); t.setAttribute('x', x0 + w + 8);
      t.textContent = `${fmtN(d.tokens)} tokens`;
      t2.setAttribute('x', x0 + w + 8);
      t2.textContent = `${fmtN(d.words)} words · ${d.chunks} chunks`;
      const hi = (k >= 1 && d.id === 'MAN-PUR-72') || (k >= 2 && (d.id.startsWith('AMD') || d.id.startsWith('HR')));
      r.style.opacity = k === 0 || hi ? 1 : 0.35;
    });
    foot.textContent = `All eight: ${fmtN(tot)} tokens.`;
  } };
};

/* ---------- Fig 3: the chunker, live, on Purchase Policy §5–§7 ---------- */
FIGS.chunker = (el) => {
  const text = D.policy_text.replace(/\*\*/g, '');
  const lines = text.split('\n');
  const words = []; // {w, sec, newline}
  let sec = '';
  lines.forEach((ln) => {
    const m2 = ln.match(/^##\s+(\d+)\./), m = ln.match(/^(\d+\.\d+)\s/);
    if (m2) sec = m2[1]; else if (m) sec = m[1];
    ln.split(/\s+/).filter(Boolean).forEach((w, i) => words.push({ w, sec, nl: i === 0 }));
  });
  el.innerHTML = `<div class="card" style="height:520px;overflow:hidden;font:18px/1.6 var(--serif);padding:14px 16px" id="ck-txt"></div>
    <div class="mini" id="ck-read" style="margin-top:10px;min-height:66px"></div>`;
  const ctl = ctlRow(el, `<button data-m="fixed" class="on">Fixed windows</button><button data-m="section">By section</button>
    <label style="margin-left:14px">Window</label><input type="range" min="20" max="100" step="5" value="60"><output></output>`);
  const box = el.querySelector('#ck-txt'), read = el.querySelector('#ck-read'), inp = ctl.querySelector('input'), out = ctl.querySelector('output');
  let mode = 'fixed';
  const tints = ['#DCEDEE', '#F1E9D2', '#E7ECE8', '#F3E2DE'];
  const draw = () => {
    const size = +inp.value;
    let idx = [];
    if (mode === 'fixed') idx = words.map((_, i) => Math.floor(i / size));
    else { let c = -1, prev = null; words.forEach((w) => { if (w.sec !== prev) { c++; prev = w.sec; } idx.push(c); }); }
    const n = idx[idx.length - 1] + 1;
    box.innerHTML = words.map((w, i) => {
      const br = w.nl && i > 0 ? '<br>' : '';
      const is62 = w.sec === '6.2';
      return `${br}<span style="background:${tints[idx[i] % 4]};${is62 ? 'box-shadow:inset 0 -3px 0 var(--gold);' : ''}${i > 0 && idx[i] !== idx[i - 1] ? 'border-left:3px solid var(--ink);padding-left:2px;' : ''}">${esc(w.w)} </span>`;
    }).join('');
    const first62 = words.findIndex((w) => w.sec === '6.2'), last62 = words.length - 1 - [...words].reverse().findIndex((w) => w.sec === '6.2');
    const c = idx[first62];
    const members = words.filter((_, i) => idx[i] === c);
    const secs = [...new Set(members.map((w) => w.sec))];
    const whole = idx[first62] === idx[last62];
    read.innerHTML = mode === 'fixed'
      ? `<b>${n} chunks</b> of ${size} words. The chunk holding §6.2 starts “${esc(members.slice(0, 7).map((w) => w.w).join(' '))}…”, mixes ${secs.map((s) => '§' + s).join(', ')}, ${whole ? 'holds all of §6.2' : '<span class="b">cuts §6.2 in two</span>'}, and has no id to cite.`
      : `<b>${n} chunks</b>, one per clause. §6.2 is one chunk of ${members.length} words, whole, with the id <span class="a">POL-PUR-001 §6.2</span>.`;
    out.textContent = mode === 'fixed' ? `${size} words` : 'clauses';
    inp.disabled = mode !== 'fixed';
  };
  ctl.querySelectorAll('button').forEach((b) => b.addEventListener('click', () => { mode = b.dataset.m; ctl.querySelectorAll('button').forEach((x) => x.classList.toggle('on', x === b)); draw(); }));
  inp.addEventListener('input', draw);
  return { step(k) { mode = k >= 2 ? 'section' : 'fixed'; ctl.querySelectorAll('button').forEach((x) => x.classList.toggle('on', x.dataset.m === mode)); draw(); } };
};

