/* ---------- Fig 5: BM25 scores for scenario 1, split by word (logs/retrieval_eval.json → s1.bm25) ---------- */
FIGS.bm25 = (el) => {
  const P = window.Plates, W = 840, H = 620;
  const t = document.getElementById('s1toks'); if (t) t.textContent = D.s1.tokens.join(' · ');
  const svg = P.svgEl('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, el);
  const rows = D.s1.bm25, max = rows[0].score, x0 = 210, bw = 520;
  const terms = [...new Set(rows.flatMap((r) => Object.keys(r.terms)))];
  const pal = ['#136C76', '#2E8B8B', '#4F7CAC', '#848B9B', '#B4B9C4', '#5C6F8A', '#7FA7A0', '#A3372B', '#8E6E12', '#C29A2E'];
  const col = (term) => term === 'better' ? '#A3372B' : pal[terms.indexOf(term) % 7];
  const groups = rows.map((r, i) => {
    const y = 20 + i * 66, g = P.svgEl('g', { style: 'transition:opacity .4s' }, svg);
    P.txt(g, x0 - 12, y + 26, r.id, `font:600 18px var(--mono);fill:${r.id === 'POL-PUR-001 §6.2' ? 'var(--after)' : 'var(--ink)'}`, 'end');
    let x = x0;
    Object.entries(r.terms).forEach(([term, v]) => {
      const w = bw * v / max;
      P.svgEl('rect', { x, y: y + 6, width: w - 1, height: 30, style: `fill:${col(term)}` }, g);
      if (w > 80) P.txt(g, x + w / 2, y + 27, term.length > 7 ? term.slice(0, 6) + '…' : term, 'font:18px var(--mono);fill:#fff', 'middle');
      x += w;
    });
    P.txt(g, x + 8, y + 27, r.score.toFixed(2), 'font:600 18px var(--mono);fill:var(--ink-2)');
    if (r.id === 'POL-PUR-001 §6.2') P.svgEl('rect', { x: x0 - 4, y: y + 2, width: x - x0 + 70, height: 38, style: 'fill:none;stroke:var(--after);stroke-width:2.5' }, g);
    return g;
  });
  const note = P.txt(svg, x0, H - 12, '', 'font:18px var(--serif);fill:var(--before)');
  return { step(k) {
    groups.forEach((g, i) => { g.style.opacity = k >= 1 ? 1 : (i < 3 ? 1 : 0.2); });
    note.textContent = k >= 3 ? `Red = “better”: ${rows[0].terms.better} of §4.2's ${rows[0].score.toFixed(2)}. Without it §4.2 would fall below §4.1.` : '';
  } };
};

/* ---------- Fig 6: the embedding space, 2-D PCA of the real vectors (logs/retrieval_eval.json → pca) ---------- */
FIGS.embed = (el) => {
  const P = window.Plates, W = 900, H = 620, pad = 40;
  const c62 = document.getElementById('cos62'); if (c62) c62.textContent = D.s1.vector[0].cos.toFixed(4);
  const pts = D.pca.points, qs = D.pca.queries;
  const xs = pts.map((p) => p[2]).concat(Object.values(qs).map((q) => q.x)), ys = pts.map((p) => p[3]).concat(Object.values(qs).map((q) => q.y));
  const [x1, x2, y1, y2] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  const sx = (x) => pad + (x - x1) / (x2 - x1) * (W - 2 * pad), sy = (y) => H - pad - (y - y1) / (y2 - y1) * (H - 2 * pad);
  el.style.position = 'absolute';
  const svg = P.svgEl('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, el);
  const tip = document.createElement('div'); tip.className = 'figtip'; el.appendChild(tip);
  const lines = P.svgEl('g', {}, svg);
  const dots = pts.map((p) => {
    const c = P.svgEl('circle', { cx: sx(p[2]), cy: sy(p[3]), r: p[0] === 'POL-PUR-001 §6.2' ? 8 : 4.5, style: `fill:${DOCCOL[p[1]]};opacity:.8;cursor:pointer;transition:opacity .4s` }, svg);
    c.addEventListener('mouseenter', () => { tip.style.display = 'block'; tip.style.left = (sx(p[2]) + 12) + 'px'; tip.style.top = (sy(p[3]) - 10) + 'px'; tip.textContent = `${p[0]} · cosine to Kavita's question ${p[4].toFixed(3)}`; });
    c.addEventListener('mouseleave', () => { tip.style.display = 'none'; });
    return { c, p };
  });
  const i62 = pts.find((p) => p[0] === 'POL-PUR-001 §6.2');
  P.txt(svg, sx(i62[2]) + 12, sy(i62[3]) + 5, '§6.2', 'font:600 18px var(--mono);fill:var(--after)');
  const star = P.svgEl('path', { d: 'M0,-14 L4,-4 L14,-4 L6,3 L9,13 L0,7 L-9,13 L-6,3 L-14,-4 L-4,-4 Z', style: 'fill:var(--ink);transition:transform .5s' }, svg);
  const lab = P.txt(svg, 0, 0, '', 'font:600 18px var(--serif);fill:var(--ink)');
  const legend = Object.keys(DOCCOL).map((d, i) => { P.svgEl('circle', { cx: 50 + (i % 4) * 215, cy: 18 + Math.floor(i / 4) * 24, r: 5, style: `fill:${DOCCOL[d]}` }, svg); return P.txt(svg, 60 + (i % 4) * 215, 24 + Math.floor(i / 4) * 24, d, 'font:18px var(--mono);fill:var(--ink-2)'); });
  const names = { s1: 'Scenario 1: food-grade certificate', P03: 'P03: approval limit, basic or gross', M01: 'M01: ERR-PO-0412', T01: 'T01 (trap): gaskets in stock' };
  const ctl = ctlRow(el, Object.keys(names).map((k) => `<button data-q="${k}">${k === 's1' ? 'Scenario 1' : k}</button>`).join('') + `<span id="em-cap" class="mini"></span>`);
  const cap = ctl.querySelector('#em-cap');
  const top5 = [...pts].sort((a, b) => b[4] - a[4]).slice(0, 5);
  const set = (key) => {
    const q = qs[key];
    star.setAttribute('transform', `translate(${sx(q.x)},${sy(q.y)})`);
    lab.setAttribute('x', sx(q.x) + 16); lab.setAttribute('y', sy(q.y) - 12); lab.textContent = names[key];
    lines.innerHTML = '';
    if (key === 's1') top5.forEach((p) => P.svgEl('line', { x1: sx(q.x), y1: sy(q.y), x2: sx(p[2]), y2: sy(p[3]), style: 'stroke:var(--after);stroke-width:1.5;stroke-dasharray:4 3' }, lines));
    ctl.querySelectorAll('button').forEach((b) => b.classList.toggle('on', b.dataset.q === key));
    cap.textContent = key === 's1' ? `dashed: the 5 highest cosines (in 384-d). PCA keeps ${(100 * (D.pca.explained[0] + D.pca.explained[1])).toFixed(0)}% of the spread, so near on paper ≠ near in 384-d.` : `PCA axes keep ${(100 * (D.pca.explained[0] + D.pca.explained[1])).toFixed(0)}% of the spread.`;
  };
  ctl.querySelectorAll('button').forEach((b) => b.addEventListener('click', () => set(b.dataset.q)));
  return { step(k) { dots.forEach(({ c }) => { c.style.opacity = k >= 2 ? 0.8 : 0.25; }); set('s1'); } };
};

