/* ---------- Fig 8: the same query, four rankings (logs/retrieval_eval.json → s1) ---------- */
FIGS.rankings = (el) => {
  const M = { bm25: ['BM25 score', D.s1.bm25.map((r) => [r.id, r.score])], vector: ['cosine', D.s1.vector.map((r) => [r.id, r.cos])],
    hybrid: ['RRF score', D.s1.hybrid.map((r) => [r.id, r.rrf])], rerank: ['reranker logit', D.s1.rerank.map((r) => [r.id, r.rerank])] };
  const names = { bm25: 'BM25', vector: 'Embeddings', hybrid: 'Hybrid (RRF)', rerank: 'Hybrid + rerank' };
  el.innerHTML = `<div class="ctl" style="margin:0 0 12px">${Object.keys(M).map((m) => `<button data-m="${m}">${names[m]}</button>`).join('')}</div><div id="rk"></div><p class="mini" id="rk-n" style="margin-top:10px"></p>`;
  const box = el.querySelector('#rk'), note = el.querySelector('#rk-n');
  const set = (m) => {
    const [unit, rows] = M[m];
    const vals = rows.map((r) => r[1]), mx = Math.max(...vals), mn = Math.min(0, ...vals);
    box.innerHTML = `<table class="t" style="font-size:19px"><thead><tr><th>#</th><th>Chunk</th><th>${unit}</th><th style="width:330px"></th></tr></thead><tbody>${rows.map(([id, v], i) =>
      `<tr style="${id === 'POL-PUR-001 §6.2' ? 'background:var(--after-soft)' : ''}"><td class="n">${i + 1}</td><td class="n" style="${id === 'POL-PUR-001 §6.2' ? 'color:var(--after);font-weight:600' : ''}">${id}</td><td class="n">${typeof v === 'number' ? (Math.abs(v) < 0.1 ? v.toFixed(5) : v.toFixed(m === 'vector' ? 4 : 3)) : v}</td>
       <td><div style="height:16px;width:${Math.max(2, 320 * (v - mn) / (mx - mn))}px;background:${v < 0 ? 'var(--before)' : 'var(--after)'};opacity:.75"></div></td></tr>`).join('')}</tbody></table>`;
    const r62 = rows.findIndex((r) => r[0] === 'POL-PUR-001 §6.2') + 1;
    note.textContent = `§6.2 is #${r62} under ${names[m]}.` + (m === 'rerank' ? ' Reranker logits: 0 = even odds; below 0 = probably not relevant.' : m === 'hybrid' ? ' RRF = 1/(60+rank BM25) + 1/(60+rank embeddings).' : '');
    el.querySelectorAll('button').forEach((b) => b.classList.toggle('on', b.dataset.m === m));
  };
  el.querySelectorAll('button').forEach((b) => b.addEventListener('click', () => set(b.dataset.m)));
  return { step(k) { set(['bm25', 'hybrid', 'rerank', 'rerank'][Math.min(k, 3)]); } };
};

