    box.innerHTML = card('Certificate age', sup ? ['AMD-SUP-2026-02 §1.1', 'answers: issued ≤ 12 months ago, ≥ 60 days left'] : ['POL-SUP-003 §4.4', 'answers: issued ≤ 24 months ago, not expired'],
      sup ? ['POL-SUP-003 §4.4'] : ['AMD-SUP-2026-02 §1.1'], sup ? 'replaced: removed from the index' : 'not yet in force: kept, labelled “applies from 2026-09-01”')
      + card('Direct-order limit', pur ? ['AMD-PUR-2026-03 §1.1', 'answers: ₹25,000'] : ['POL-PUR-001 §3.3', 'answers: ₹50,000'],
        pur ? ['POL-PUR-001 §3.3'] : ['AMD-PUR-2026-03 §1.1'], pur ? 'replaced: removed from the index' : 'not yet in force: kept, labelled “applies from 2026-12-01”');
