  const lo = ans.reduce((a, b) => (b.top < a.top ? b : a)), hi = una.reduce((a, b) => (b.top > a.top ? b : a));
  const a1 = document.getElementById('tau-lo'); if (a1) a1.textContent = `${lo.top.toFixed(2)} (${lo.id})`;
  const a2 = document.getElementById('tau-hi'); if (a2) a2.textContent = `${hi.top.toFixed(2)} (${hi.id})`;
  const sx = (v) => 60 + (v + 3) / 13 * (W - 100);
  [-2, 0, 2, 4, 6, 8, 10].forEach((v) => { P.svgEl('line', { x1: sx(v), x2: sx(v), y1: 90, y2: 470, style: 'stroke:var(--rule)' }, svg); P.txt(svg, sx(v), 495, v, 'font:18px var(--mono);fill:var(--ink-3)', 'middle'); });
  P.txt(svg, W / 2, 530, 'best reranker score among the clauses retrieved (logit)', 'font:18px var(--serif);fill:var(--ink-2)', 'middle');
  const row = (list, y, col, label) => {
    const g = P.svgEl('g', { style: 'transition:opacity .4s' }, svg);
    P.txt(g, 60, y - 50, label, `font:600 18px var(--mono);fill:${col}`);
    list.forEach((t, i) => { P.svgEl('circle', { cx: sx(t.top), cy: y + ((i % 5) - 2) * 9, r: 7, style: `fill:${col};opacity:.75` }, g); });
    return g;
  };
  const gA = row(ans, 200, 'var(--after)', `answerable (${ans.length})`), gU = row(una, 400, 'var(--before)', `not in the documents (${una.length}: 2 HR, 5 traps)`);
  const lab = P.svgEl('g', { style: 'transition:opacity .4s' }, svg);
