/* ---------- Fig 16: the wiki as linked pages (logs/wiki_compile.json → pages[].links) ---------- */
FIGS.wikigraph = (el) => {
  const P = window.Plates, W = 950, H = 610;
  const pg = D.wiki.pages, slugs = Object.keys(pg), open = slugs.filter((s) => pg[s].audience !== 'hr only'), hr = slugs.filter((s) => pg[s].audience === 'hr only');
  const ws = document.getElementById('wiki-size');
  const tot = Object.values(D.wiki.page_tokens).reduce((a, b) => a + b, 0);
  if (ws) ws.textContent = `${slugs.length} pages, ${fmtN(tot)} tokens in all. The index that a question reads first is ${fmtN(D.wiki.index_tokens)} tokens.`;
  const svg = P.svgEl('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, el);
  const pos = {}, cx = 400, cy = 300, R = 250;
  open.forEach((s, i) => { const a = -Math.PI / 2 + i * 2 * Math.PI / open.length; pos[s] = [cx + R * Math.cos(a), cy + R * Math.sin(a)]; });
  hr.forEach((s, i) => { pos[s] = [W - 70, 80 + i * 60]; });
  const edges = P.svgEl('g', {}, svg);
  const E = [];
  slugs.forEach((s) => pg[s].links.forEach((t) => { if (pos[t]) E.push([s, t, P.svgEl('line', { x1: pos[s][0], y1: pos[s][1], x2: pos[t][0], y2: pos[t][1], style: 'stroke:var(--rule);stroke-width:1.5' }, edges)]); }));
  const info = document.createElement('div'); info.className = 'card'; info.style.cssText = 'position:absolute;left:640px;top:420px;width:300px;font-size:18px';
  el.style.position = 'absolute'; el.appendChild(info);
  const nodes = slugs.map((s) => {
    const [x, y] = pos[s], tok = D.wiki.page_tokens[s], r = 10 + Math.sqrt(tok) / 3;
    const c = P.svgEl('circle', { cx: x, cy: y, r, style: `fill:${pg[s].audience === 'hr only' ? 'var(--before-soft)' : pg[s].audience === 'all purchase staff' ? 'var(--after-soft)' : 'var(--paper-2)'};stroke:${pg[s].audience === 'hr only' ? 'var(--before)' : 'var(--after)'};stroke-width:2;cursor:pointer` }, svg);
    const t = P.txt(svg, x, y + r + 14, s.split('-')[0], 'font:18px var(--mono);fill:var(--ink-2);pointer-events:none', 'middle');
    c.addEventListener('click', () => sel(s));
    return { s, c, t };
  });
  const sel = (s) => {
    const p = pg[s];
    E.forEach(([a, b, l]) => { const on = a === s || b === s; l.style.stroke = on ? 'var(--after)' : 'var(--rule)'; l.style.strokeWidth = on ? 3 : 1.5; });
    nodes.forEach((n) => { n.c.style.strokeWidth = n.s === s ? 4 : 2; });
    info.innerHTML = `<b>${esc(p.title)}</b><div class="mini">[[${s}]] · ${p.audience}</div><div>${p.n_sources} source clauses · ${fmtN(D.wiki.page_tokens[s])} tokens · ${p.links.length} links</div>`;
  };
  return { step(k) { edges.style.opacity = k >= 0 ? 1 : 0; sel(k >= 1 ? hr[0] : 'food-grade-compliance'); } };
};

